(()=>{
 const root=document.getElementById('knowledge'),ui=KNOWLEDGE.ui,articles=KNOWLEDGE.articles;
 const byId=id=>document.getElementById(id);let category='all',query='',lastTrigger=null;
 function tag(t,cls,text){const e=document.createElement(t);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e}
 function text(id,value){byId(id).textContent=value}
 for(const key of ['title','subtitle','search','draft','scope'])text('kb-'+key,ui[key]);
 text('kb-archive-note',ui.archiveNote);text('kb-original-label',ui.original);text('kb-source-label',ui.sources);text('kb-close-label',ui.close);
 byId('kb-query').setAttribute('aria-label',ui.search);byId('kb-query').placeholder=ui.search;
 byId('kb-search-toggle').setAttribute('aria-label',ui.search);byId('kb-clear').setAttribute('aria-label',ui.clear);byId('kb-close').setAttribute('aria-label',ui.close);
 byId('kb-jump').setAttribute('aria-label',ui.title);byId('kb-jump').title=ui.title;byId('kb-meta-toggle').setAttribute('aria-label',ui.original);text('kb-meta-values',KNOWLEDGE.archive.documents+' · '+KNOWLEDGE.archive.sizeLabel);byId('kb-meta-toggle').onclick=()=>{const open=root.classList.toggle('kb-meta-open');byId('kb-meta-toggle').setAttribute('aria-expanded',String(open));};
 const stat=byId('kb-stats');for(const [value,label] of [[articles.length,ui.topics],[KNOWLEDGE.archive.documents,ui.sourceCount],[KNOWLEDGE.archive.sizeLabel,ui.size],['100 GB',ui.limit.split('᠄')[0]]]){const box=tag('div','kb-stat');box.append(tag('strong','',value),tag('span','mn',label));stat.append(box)}
 text('kb-collected',ui.collected+' · '+KNOWLEDGE.archive.collectedAt);

 text('kb-originals-title',ui.original);for(const r of KNOWLEDGE.readings||[]){const a=tag('a','kb-original');a.href=r.url;a.target='_blank';a.rel='noopener noreferrer';a.append(tag('strong','mn',r.titleMn),tag('span','mn',r.summaryMn));if(r.accessNoteMn)a.append(tag('span','mn kb-original-access',r.accessNoteMn));byId('kb-originals-list').append(a)}byId('kb-originals').hidden=!(KNOWLEDGE.readings||[]).length;
 const categories=['all',...new Set(articles.map(a=>a.category))];
 for(const id of categories){const b=tag('button','kb-category mn',id==='all'?ui.all:ui.categories[id]);b.type='button';b.dataset.category=id;b.setAttribute('aria-pressed',id==='all'?'true':'false');b.onclick=()=>{category=id;root.querySelectorAll('[data-category]').forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.category===id)));render()};byId('kb-categories').append(b)}
 function render(){const list=byId('kb-list');list.replaceChildren();const normalized=query.normalize('NFKC').toLowerCase();const filtered=articles.filter(a=>(category==='all'||a.category===category)&&(!normalized||[a.title,a.summary,...a.body].join(' ').normalize('NFKC').toLowerCase().includes(normalized)));text('kb-count',filtered.length+' / '+articles.length);byId('kb-empty').hidden=filtered.length>0;text('kb-empty',ui.empty);for(const a of filtered){const button=tag('button','kb-card');button.type='button';button.dataset.article=a.id;button.setAttribute('aria-label',a.title);const spine=tag('span','kb-spine');spine.append(tag('span','kb-number',String(articles.indexOf(a)+1).padStart(2,'0')),tag('span','kb-topic mn',ui.categories[a.category]));const words=tag('span','kb-card-words');words.append(tag('strong','mn',a.title),tag('span','kb-summary mn',a.summary));button.append(spine,words,tag('span','kb-open-mark','＋'));button.onclick=()=>openArticle(a,button);list.append(button)}}
 function openArticle(a,button){lastTrigger=button;text('kb-reader-title',a.title);text('kb-reader-category',ui.categories[a.category]);const copy=byId('kb-reader-copy');copy.replaceChildren();for(const p of a.body)copy.append(tag('p','',p));const sources=byId('kb-reader-sources');sources.replaceChildren();for(const s of a.sources){const link=tag('a','',s.nameMn||s.title);link.href=s.url;link.target='_blank';link.rel='noopener noreferrer';sources.append(link)}const people=byId('kb-reader-people');people.replaceChildren();people.hidden=!(a.relatedPeople||[]).length;if(!people.hidden){people.append(tag('h3','',ui.graph||'ᠬᠣᠯᠪᠤᠭᠠᠨ ᠤ ᠵᠢᠷᠤᠭ'));for(const id of a.relatedPeople){if(!PEOPLE[id])continue;const b=tag('button','mn',PEOPLE[id].name);b.type='button';b.dataset.graphPerson=id;b.onclick=()=>{lastTrigger=null;byId('kb-reader').close();document.dispatchEvent(new CustomEvent('atlas:focus-person',{detail:{id,mode:a.relatedModes?.[id]||a.graphMode||'family'}}));};people.append(b)}}if(!byId('kb-reader').open)byId('kb-reader').showModal();byId('kb-reader-scroll').scrollLeft=0}
 function addRelatedReadings(){const panel=byId('detail'),id=panel.dataset.person;panel.querySelector('.person-readings')?.remove();const matching=articles.filter(a=>(a.relatedPeople||[]).includes(id));if(!matching.length)return;const box=tag('section','person-readings');box.append(tag('h3','',ui.title));for(const a of matching){const b=tag('button','mn',a.title);b.type='button';b.dataset.relatedArticle=a.id;b.onclick=()=>openArticle(a,b);box.append(b)}panel.append(box)}document.addEventListener('atlas:person-selected',addRelatedReadings);addRelatedReadings();
 byId('kb-close').onclick=()=>byId('kb-reader').close();byId('kb-reader').addEventListener('close',()=>lastTrigger?.focus());byId('kb-reader').addEventListener('click',e=>{if(e.target===byId('kb-reader')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
 byId('kb-search-toggle').onclick=()=>{const open=root.classList.toggle('kb-search-open');byId('kb-search-toggle').setAttribute('aria-expanded',String(open));if(open)byId('kb-query').focus();};byId('kb-query').addEventListener('keydown',e=>{if(e.key==='Escape'){root.classList.remove('kb-search-open');byId('kb-search-toggle').setAttribute('aria-expanded','false');byId('kb-search-toggle').focus();}});
 byId('kb-query').addEventListener('input',e=>{query=e.target.value;byId('kb-search-toggle').classList.toggle('has-query',Boolean(query.trim()));render()});byId('kb-clear').onclick=()=>{query='';byId('kb-query').value='';byId('kb-search-toggle').classList.remove('has-query');render();byId('kb-query').focus()};byId('kb-jump').onclick=()=>root.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});render();
function openFragment(){const id=new URLSearchParams(location.hash.slice(1)).get('article');const article=articles.find(a=>a.id===id);if(article)openArticle(article,null)}window.addEventListener('hashchange',openFragment);openFragment();
})();
